# instmodel: each rule of src/quest/combat/instmodel.cpp and instmodel_targets.h removed or bent once; src/quest/tests/instmodel_test.cpp must
# fail on every one. Sourced by ../mutants.sh, which defines `runm <name> <file> <sed>`.
S=src/quest/combat/instmodel.cpp
T=src/quest/combat/instmodel_targets.h
# the scope: the steps only in a combat match
runm im_scope_inverted      $S "s/  if (scope != table_step::Scope::kCombat) {/  if (scope == table_step::Scope::kCombat) {/"
runm im_always_sets         $S "s/  if (scope != table_step::Scope::kCombat) {/  if (false) {/"
runm im_never_sets          $S "s/  if (scope != table_step::Scope::kCombat) {/  if (true) {/"
runm im_scope_not_read      $S "s/self != nullptr ? table_step::CurrentScope() : table_step::Scope::kUnknown;/table_step::Scope::kCombat;/"
runm im_null_self_is_read   $S "s/self != nullptr ? table_step::CurrentScope() : table_step::Scope::kUnknown;/table_step::CurrentScope();/"
# the game's constructor runs once, for every call, before the steps are touched
runm im_original_dropped    $S "s/^  original(self, init);\$/  (void)original; (void)init;/"
runm im_original_args       $S "s/^  original(self, init);\$/  (void)init; original(self, self);/"
runm im_stock_not_counted   $S "s/g_stock.fetch_add(1, std::memory_order_relaxed);/g_stock.fetch_add(0, std::memory_order_relaxed);/"
runm im_stock_said_always   $S "s/  if (g_saidStock.exchange(true, std::memory_order_relaxed)) return;/  (void)g_saidStock;/"
runm im_stock_scope_unnamed $S "s/table_step::ScopeName(scope)/(scope == table_step::Scope::kUnknown ? \"combat\" : \"other\")/"
# the eight steps
runm im_new_step_two        $S "s/constexpr std::uint64_t kNewStep = 1;/constexpr std::uint64_t kNewStep = 2;/"
runm im_stock_step_other    $S "s/constexpr std::uint64_t kStockStep = 0x20;/constexpr std::uint64_t kStockStep = 0x21;/"
runm im_step_offset         $S "s/constexpr std::uintptr_t kStepOffset = 0x20;/constexpr std::uintptr_t kStepOffset = 0x28;/"
runm im_first_member        $S "s/{0x78, 0xb0,/{0x80, 0xb0,/"
runm im_second_member       $S "s/0x78, 0xb0, 0xe8,/0x78, 0xb8, 0xe8,/"
runm im_third_member        $S "s/0xb0, 0xe8, 0x120,/0xb0, 0xf0, 0x120,/"
runm im_fourth_member       $S "s/0xe8, 0x120, 0x158,/0xe8, 0x128, 0x158,/"
runm im_fifth_member        $S "s/0x120, 0x158, 0x190,/0x120, 0x160, 0x190,/"
runm im_sixth_member        $S "s/0x158, 0x190, 0x1c8,/0x158, 0x198, 0x1c8,/"
runm im_seventh_member      $S "s/0x190, 0x1c8, 0x200};/0x190, 0x1d0, 0x200};/"
runm im_eighth_member       $S "s/0x1c8, 0x200};/0x1c8, 0x208};/"
runm im_last_member_dropped $S "s/0x1c8, 0x200};/0x1c8};/"
runm im_first_member_dropped $S "s/{0x78, 0xb0, 0xe8,/{0xb0, 0xe8,/"
runm im_mismatch_overwritten $S "s/^    if (have != kStockStep) {\$/    if (false) {/"
runm im_mismatch_inverted   $S "s/^    if (have != kStockStep) {\$/    if (have == kStockStep) {/"
runm im_mismatch_not_counted $S "s/^      ++\*mismatch;\$/      (void)mismatch;/"
runm im_set_not_counted     $S "s/^    ++set;\$//"
runm im_write_dropped       $S "s/^    std::memcpy(self + at, \&one, sizeof one);\$/    (void)one;/"
runm im_object_not_counted  $S "s/g_objects.fetch_add(1, std::memory_order_relaxed);/g_objects.fetch_add(0, std::memory_order_relaxed);/"
runm im_steps_not_summed    $S "s/g_stepsSet.fetch_add(set, std::memory_order_relaxed);/g_stepsSet.fetch_add(0, std::memory_order_relaxed);/"
runm im_mismatch_not_summed $S "s/g_mismatch.fetch_add(mismatch, std::memory_order_relaxed);/g_mismatch.fetch_add(0, std::memory_order_relaxed);/"
# the log: the first sixteen, then the cap line, each field named
runm im_log_cap_seventeen   $S "s/constexpr unsigned kLogLines = 16;/constexpr unsigned kLogLines = 17;/"
runm im_log_no_cap_line     $S "s/  if (n == kLogLines + 1) {/  if (false) {/"
runm im_log_uncapped        $S "s/  if (n > kLogLines) return;/  (void)kLogLines;/"
runm im_mismatch_uncapped   $S "s/g_mismatchLines.fetch_add(1, std::memory_order_relaxed) < kLogLines/true/"
runm im_mismatch_offset     $S "s/{\"offset\", sentinel::HexString(off, at)}/{\"offset\", sentinel::HexString(off, member)}/"
runm im_mismatch_found      $S "s/{\"found\", sentinel::HexString(found, have)}/{\"found\", sentinel::HexString(found, kStockStep)}/"
runm im_steps_level_debug   $S "s/sentinel::LogFields(sentinel::LogLevel::kDebug, \"combat_instmodel_steps\"/sentinel::LogFields(sentinel::LogLevel::kInfo, \"combat_instmodel_steps\"/"
runm im_mismatch_level_info $S "s/sentinel::LogFields(sentinel::LogLevel::kWarn, \"combat_instmodel_mismatch\"/sentinel::LogFields(sentinel::LogLevel::kInfo, \"combat_instmodel_mismatch\"/"
runm im_steps_text          $S "s/{\"steps_set\", set}, {\"steps_mismatch\", mismatch}/{\"steps_set\", mismatch}, {\"steps_mismatch\", set}/"
# the install: the pins, the build, the switch, once, the slot
runm im_pins_skipped        $S "s/if (const table_step::PinWord\* const bad = table_step::FirstPinMismatch(image.base, kWords, kWordCount, \&have, \&readable)) {/if (const table_step::PinWord* const bad = (table_step::FirstPinMismatch(image.base, kWords, kWordCount, \&have, \&readable), nullptr)) {/"
runm im_last_pin_skipped    $S "s/FirstPinMismatch(image.base, kWords, kWordCount,/FirstPinMismatch(image.base, kWords, kWordCount - 1,/"
runm im_first_pin_skipped   $S "s/FirstPinMismatch(image.base, kWords, kWordCount,/FirstPinMismatch(image.base, kWords + 1, kWordCount - 1,/"
runm im_first_word_pin      $T "s/inline constexpr std::uint32_t kStockCtorFirstWord = 0xf81e0ff4;/inline constexpr std::uint32_t kStockCtorFirstWord = 0xf81e0ff5;/"
runm im_step_word_pin       $T "s/inline constexpr std::uint32_t kStockStepWord = 0x52800414;/inline constexpr std::uint32_t kStockStepWord = 0x52800415;/"
runm im_off_ignored         $S "s/^  if (!on) return Done(/  if (!on \&\& false) return Done(/"
runm im_second_step_runs    $S "s/  if (g_ran.exchange(true, std::memory_order_acq_rel)) return/  if (false) return/"
runm im_no_expected_ctor    $T "s/^  target.expectedOriginal = .*\$/  (void)base;/"
runm im_expected_wrong      $T "s/base + pins.ctor);/base + pins.ctor + 4);/"
runm im_slot_pin_off        $T "s/^                             pins.slot);\$/                             pins.slot + 8);/"
runm im_kind_glob_dat       $T "s/sentinel::RelocKind::kJumpSlot, sentinel::pinned::LibR15PatchedBuildId(),/sentinel::RelocKind::kGlobDat, sentinel::pinned::LibR15PatchedBuildId(),/"
runm im_slot_wrong          $T "s/inline constexpr Pins kPins = {0x19078dc, 0x36c5c68, 0x1907958};/inline constexpr Pins kPins = {0x19078dc, 0x36c5c70, 0x1907958};/"
runm im_ctor_wrong          $T "s/inline constexpr Pins kPins = {0x19078dc, 0x36c5c68, 0x1907958};/inline constexpr Pins kPins = {0x19078e0, 0x36c5c68, 0x1907958};/"
runm im_legacy_not_warned   $S "s/^  table_step::WarnLegacySwitch(.*\$//"
runm im_legacy_file_name    $S "s/\"instmodel.off\", \"combat.instmodel: false\"/\"instmodel.of\", \"combat.instmodel: false\"/"
runm im_legacy_key_name     $S "s/\"instmodel.off\", \"combat.instmodel: false\"/\"instmodel.off\", \"combat.instmodel: true\"/"
runm im_refusal_not_error   $S "s/refused ? sentinel::LogLevel::kError : sentinel::LogLevel::kInfo/refused ? sentinel::LogLevel::kInfo : sentinel::LogLevel::kInfo/"
runm im_install_slot_text   $S "s/sentinel::HexString(slot, pins.slot)/sentinel::HexString(slot, pins.ctor)/"
runm im_installed_status    $S "s/return Done(\"installed\", \"ok\", \"installed\",/return Done(\"installed\", \"ok\", \"ok\",/"
# the arena path writes nothing to the game's object (the test compares the whole object with the game's own)
runm im_stray_write_low     $S "s/^    SayStock(scope);\$/    SayStock(scope);\n    static_cast<unsigned char*>(self)[0x10] = 1;/"
runm im_stray_write_step    $S "s/^    SayStock(scope);\$/    SayStock(scope);\n    static_cast<unsigned char*>(self)[0x98] = 1;/"
runm im_counts_not_registered $S "s/^  table_step::RegisterCounts(.*\$//"
runm im_counts_swapped      $S "s/return {g_stock.load(std::memory_order_relaxed), g_objects.load(std::memory_order_relaxed)};/return {g_objects.load(std::memory_order_relaxed), g_stock.load(std::memory_order_relaxed)};/"
runm im_cap_line_level      $S "s/sentinel::LogFields(sentinel::LogLevel::kInfo, \"combat_instmodel_log_cap\"/sentinel::LogFields(sentinel::LogLevel::kDebug, \"combat_instmodel_log_cap\"/"
